class InheritedEvidenceTests(unittest.TestCase):
 def test_actual_raw_evidence_bytes_preserved(self):
  for name,digest in EXPECTED.items():self.assertEqual(hashlib.sha256((ROOT/name).read_bytes()).hexdigest(),digest,name)
 def test_manual_span_is_exact_nominal_mapping(self):
  p=json.loads((ROOT/'PROTOCOL.json').read_text());m=p['geometry']['bin_mapping'];chosen=[r for r in m if r['frames_inclusive'][1]>=56 and r['frames_inclusive'][0]<=127]
  self.assertEqual([r['bin'] for r in chosen],list(range(17,38)));self.assertEqual(chosen[0]['frames_inclusive'][0],56);self.assertEqual(chosen[-1]['frames_inclusive'][1],127)
  self.assertEqual(p['schedule']['active_indices'],list(range(6,15)))
